head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getSubmissionList]<br/>현재 Scope 내의 모든 Submission 객체를 반환합니다.",
    "validation" : [
        "options(선택) 파라미터로 반환 정보를 변경하는 옵션 객체를 설정할 수 있어야 합니다.",
        "options.returnType(선택) 파라미터로 'obj', 'json', 'id' 중 하나를 지정할 수 있어야 하며, 반환 형식이 설정값에 따라 달라져야 합니다.",
        "options.returnType 생략 시 기본값 'obj' 로 동작하여 Submission 객체 배열을 반환해야 합니다.",
        "options.all(선택) 파라미터로 true / false 를 설정할 수 있어야 하며, true 시 전체 화면을 대상으로, false 시 현재 Scope 만을 대상으로 조회해야 합니다.",
        "options.all 생략 시 기본값 false 로 동작하여 현재 Scope 내 Submission 만 반환해야 합니다.",
        "options 파라미터 생략 시 기본값(returnType='obj', all=false) 으로 동작해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getSubmissionList_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 기본값 (현재 Scope / returnType='obj')
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 메인에서 $p.getSubmissionList() 호출 (기본값) ──");
        var list1 = $p.getSubmissionList();
        var type1 = Array.isArray(list1) ? "Array" : (typeof list1);
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + type1 + " / 길이 : " + list1.length);
        for (var i = 0; i < list1.length; i++) {
            var item = list1[i];
            var itemType = typeof item;
            var id = (item && item.id) ? item.id : "-";
            var action = (item && item.action) ? item.action : "-";
            var method = (item && item.method) ? item.method : "-";
            var mediatype = (item && item.mediatype) ? item.mediatype : "-";
            wf_body_bottom.getObj("scwin").setReturnValue(
                "[" + i + "] typeof=" + itemType +
                " / id=" + id +
                " / action=" + action +
                " / method=" + method +
                " / mediatype=" + mediatype
            );
        }
    } else if (scenario === "2") {
        // 시나리오 2 : returnType='id' (ID 문자열 배열)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : $p.getSubmissionList({returnType:'id'}) ──");
        var list2 = $p.getSubmissionList({"returnType" : "id"});
        var type2 = Array.isArray(list2) ? "Array" : (typeof list2);
        var isStr = (list2 && list2[0]) ? (typeof list2[0] === "string") : false;
        wf_body_bottom.getObj("scwin").setReturnValue(
            "반환 타입 : " + type2 +
            " / 길이 : " + list2.length +
            " / 문자열 여부 : " + isStr +
            " / 값 : [" + list2.join(", ") + "]"
        );
    } else if (scenario === "3") {
        // 시나리오 3 : returnType='json' + all=true (전체 화면 JSON)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : $p.getSubmissionList({returnType:'json', all:true}) ──");
        var list3 = $p.getSubmissionList({"returnType" : "json", "all" : true});
        var type3 = (list3 === null) ? "null" : (Array.isArray(list3) ? "Array" : (typeof list3));
        var keys = list3 ? Object.keys(list3) : [];
        wf_body_bottom.getObj("scwin").setReturnValue(
            "반환 타입 : " + type3 + " (JSON 객체) / Scope 키 목록 : [" + keys.join(", ") + "]"
        );
        for (var i = 0; i < keys.length; i++) {
            var k = keys[i];
            var ids = list3[k] || [];
            wf_body_bottom.getObj("scwin").setReturnValue(
                "  Scope '" + k + "' → Submission IDs : [" + ids.join(", ") + "]"
            );
        }
    } else if (scenario === "4") {
        // 시나리오 4 : all=false (기본값) + returnType='id'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : $p.getSubmissionList({returnType:'id', all:false}) ──");
        var list4 = $p.getSubmissionList({"returnType" : "id", "all" : false});
        wf_body_bottom.getObj("scwin").setReturnValue(
            "현재 Scope 내 Submission IDs : [" + list4.join(", ") + "] / 길이 : " + list4.length
        );
        wf_body_bottom.getObj("scwin").setReturnValue(
            "(전체 Scope 가 아닌 현재 메인 Scope 의 sbm_main_1, sbm_main_2 만 반환)"
        );
    } else if (scenario === "5") {
        // 시나리오 5 : WFrame 내부 호출 안내
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 5 : WFrame 내부에서 $p.getSubmissionList 호출 ──");
        wf_body_bottom.getObj("scwin").setReturnValue(
            "아래 grp_comp 영역의 wf1 내부 버튼 'wf1 내부에서 getSubmissionList (현재 Scope)' 를 클릭하여"
        );
        wf_body_bottom.getObj("scwin").setReturnValue(
            "WFrame Scope 내부의 Submission(sbm_wf1_1, sbm_wf1_2) 만 반환되는지 확인하세요."
        );
    }
};
